	@ParameterizedTest
	@ValueSource(strings = { "short-key", "zero-terminal", "negative-terminal", "wrong-bucket", "key-terminal",
			"duplicate-raw", "duplicate-old-cold", "overlapping-buckets" })
	void malformedPackedPrefixesAndCrossFamilyConflictsFailClosed(String problem, @TempDir Path directory)
			throws Exception {
		try (Fixture fixture = new Fixture(directory)) {
			int count = problem.equals("overlapping-buckets") ? 32 : 3;
			for (int index = 0; index < count; index++) {
				fixture.commit(statement(fixture.head() + 1, "v"));
				if (index == 0) {
					fixture.gate.awaitSelected();
				}
			}
			long first = fixture.baseline + 1;
			Map<Long, Storage> omitted = new LinkedHashMap<>();
			omitted.put(first, Storage.OMIT);
			if (problem.equals("overlapping-buckets")) {
				omitted.put(first + 10, Storage.OMIT);
				omitted.put(first + 20, Storage.OMIT);
				omitted.put(first + 30, Storage.OMIT);
			}
			fixture.rehome(omitted, Set.of(), (stack, transaction) -> {
				byte[] encoded = pack(List.of(fixture.expected.get(first)));
				int bucket = packedBucket(first);
				byte[] packedKey = key(0, first);
				switch (problem) {
				case "short-key" -> packedKey = Arrays.copyOf(packedKey, packedKey.length - 1);
				case "zero-terminal" -> packedKey = key(0, 0);
				case "negative-terminal" -> packedKey = key(0, -1);
				case "wrong-bucket" -> bucket = (bucket + 1) & 31;
				case "key-terminal" -> {
					packedKey = key(0, first + 1);
					bucket = packedBucket(first + 1);
				}
				case "duplicate-raw" -> putRaw(stack, transaction, fixture.expected.get(first), false);
				case "duplicate-old-cold" -> put(stack, transaction, COLD, longKey(first), encoded);
				case "overlapping-buckets" -> {
					long leftLast = first + 20;
					long rightLast = first + 30;
					assertTrue(packedBucket(leftLast) != packedBucket(rightLast));
					put(stack, transaction, bucketName(packedBucket(leftLast)), key(0, leftLast),
							pack(List.of(fixture.expected.get(first), fixture.expected.get(leftLast))));
					put(stack, transaction, bucketName(packedBucket(rightLast)), key(0, rightLast),
							pack(List.of(fixture.expected.get(first + 10), fixture.expected.get(rightLast))));
					return;
				}
				default -> throw new AssertionError(problem);
				}
				put(stack, transaction, bucketName(bucket), packedKey, encoded);
			});
			assertThrows(IOException.class,
					() -> fixture.triples().listBackupStageTransactions(fixture.baseline, Long.MAX_VALUE),
					"Source enumeration must reject " + problem + " rather than selecting arbitrary stage history");
			if (problem.startsWith("duplicate-")) {
				assertThrows(IOException.class, () -> fixture.triples().readBackupStageHeader(first));
			}
		}
	}

	private enum Storage {
		RAW,
		PACKED,
		OLD_COLD,
		OMIT
	}

	private static int packedBucket(long terminal) {
		return (int) ((terminal / 10) & 31);
	}

	private static String bucketName(int bucket) {
		return LmdbBackupOutbox.bucketDatabaseName(bucket);
	}

	private static byte[] key(long transaction, long chunk) {
		return ByteBuffer.allocate(2 * Long.BYTES)
				.order(ByteOrder.BIG_ENDIAN)
				.putLong(transaction)
				.putLong(chunk)
				.array();
	}

	private static byte[] longKey(long transaction) {
		return ByteBuffer.allocate(Long.BYTES).putLong(transaction).array();
	}

	private static Statement statement(long transaction, String label) {
		var values = SimpleValueFactory.getInstance();
		return values.createStatement(values.createIRI("urn:packed-edge:" + transaction),
				values.createIRI("urn:p"), values.createLiteral(label));
	}

	private static String entropy(int length) {
		SplittableRandom random = new SplittableRandom(193);
		StringBuilder value = new StringBuilder(length);
		for (int index = 0; index < length; index++) {
			value.append((char) ('!' + random.nextInt(90)));
		}
		return value.toString();
	}

	private static void add(LmdbStore store, Statement value) {
		try (var connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(value.getSubject(), value.getPredicate(), value.getObject());
			connection.commit();
		}
	}

	private static int database(MemoryStack stack, long transaction, String name) throws IOException {
		var handle = stack.mallocInt(1);
		E(name == null ? mdb_dbi_open(transaction, (ByteBuffer) null, 0, handle)
				: mdb_dbi_open(transaction, name, 0, handle));
		return handle.get(0);
	}

	private static byte[] get(MemoryStack stack, long transaction, String name, byte[] keyBytes) throws IOException {
		MDBVal key = MDBVal.malloc(stack).mv_data(stack.bytes(keyBytes));
		MDBVal value = MDBVal.malloc(stack);
		int result = mdb_get(transaction, database(stack, transaction, name), key, value);
		if (result == MDB_NOTFOUND) {
			return null;
		}
		E(result);
		byte[] bytes = new byte[(int) value.mv_size()];
		value.mv_data().get(bytes);
		return bytes;
	}

	private static byte[] nativeValue(TripleStore triples, String database, byte[] key) throws IOException {
		return triples.getTxnManager()
				.doWithFreshPriority((stack, transaction) -> get(stack, transaction, database, key));
	}

	private static void put(MemoryStack stack, long transaction, String name, byte[] keyBytes, byte[] bytes)
			throws IOException {
		ByteBuffer storage = MemoryUtil.memAlloc(bytes.length);
		try {
			MDBVal key = MDBVal.malloc(stack).mv_data(stack.bytes(keyBytes));
			MDBVal value = MDBVal.malloc(stack).mv_data(storage.put(bytes).flip());
			E(mdb_put(transaction, database(stack, transaction, name), key, value, 0));
		} finally {
			MemoryUtil.memFree(storage);
		}
	}

	private static byte[] frame(byte[] bytes) throws IOException {
		assertTrue(bytes.length <= CHUNK_BYTES);
		LmdbBackupChunkCodec.Encoder encoder = new LmdbBackupChunkCodec.Encoder();
		int length = encoder.encode(bytes, bytes.length);
		return Arrays.copyOf(encoder.bytes(), length);
	}

	private static byte[] pack(List<Expected> stages) throws IOException {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (DataOutputStream output = new DataOutputStream(bytes)) {
			output.writeInt(PACK_MAGIC);
			output.writeInt(stages.size());
			long previous = 0;
			for (Expected stage : stages) {
				assertTrue(stage.stage().transaction > previous);
				byte[] frame = frame(stage.bytes());
				assertTrue(frame.length <= 256, "Only actual small complete frames belong in a packed fixture");
				output.writeLong(stage.stage().transaction);
				output.writeInt(frame.length);
				output.write(frame);
				previous = stage.stage().transaction;
			}
			CRC32C checksum = new CRC32C();
			checksum.update(bytes.toByteArray());
			output.writeInt((int) checksum.getValue());
		}
		return bytes.toByteArray();
	}

	private static void putRaw(MemoryStack stack, long transaction, Expected stage, boolean headerless)
			throws IOException {
		byte[] bytes = stage.bytes();
		if (headerless) {
			assertTrue(bytes.length > CHUNK_BYTES, "A headerless fixture must retain a real continuation");
		}
		for (int offset = headerless ? CHUNK_BYTES : 0,
				chunk = headerless ? 1 : 0; offset < bytes.length; offset += CHUNK_BYTES, chunk++) {
			byte[] raw = Arrays.copyOfRange(bytes, offset, Math.min(bytes.length, offset + CHUNK_BYTES));
			put(stack, transaction, bucketName((int) (stage.stage().transaction & 31)),
					key(stage.stage().transaction, chunk), frame(raw));
		}
	}

	private static void assertProof(TripleStore triples, long boundary, UUID identity) throws IOException {
		triples.getTxnManager().doWithFreshPriority((stack, transaction) -> {
			assertProof(stack, transaction, boundary, identity);
			return null;
		});
	}

	private static void assertProof(MemoryStack stack, long transaction, long boundary, UUID identity)
			throws IOException {
		byte[] bytes = get(stack, transaction, TripleStore.NAMESPACE_DATABASE_NAME, ACK_KEY);
		assertNotNull(bytes, "The actual source writer must persist its real publication proof");
		assertEquals(new Acknowledgement(identity, boundary), TripleStore.decodeBackupAcknowledgement(bytes));
	}

	private static Stage latest(TripleStore triples, long namespaceBoundary) throws IOException {
		return triples.getTxnManager().doWithFreshPriority((stack, transaction) -> {
			int[] buckets = new int[32];
			for (int index = 0; index < buckets.length; index++) {
				buckets[index] = database(stack, transaction, bucketName(index));
			}
			int main = database(stack, transaction, null);
			MDBStat statistics = MDBStat.malloc(stack);
			E(mdb_stat(transaction, main, statistics));
			try (LmdbBackupOutbox reader = new LmdbBackupOutbox(-1, buckets, database(stack, transaction, HOT),
					database(stack, transaction, COLD), statistics.ms_psize(), main)) {
				return reader.latestStage(stack, transaction, namespaceBoundary);
			}
		});
	}

	private static byte[] sourceSnapshot(TripleStore triples) throws IOException {
		return triples.getTxnManager().doWithFreshPriority((stack, transaction) -> {
			ByteArrayOutputStream bytes = new ByteArrayOutputStream();
			try (DataOutputStream output = new DataOutputStream(bytes)) {
				List<String> names = new ArrayList<>(List.of(HOT, COLD));
				for (int index = 0; index < 32; index++) {
					names.add(bucketName(index));
				}
				for (String name : names) {
					output.writeUTF(name);
					var handle = stack.mallocPointer(1);
					E(mdb_cursor_open(transaction, database(stack, transaction, name), handle));
					long cursor = handle.get(0);
					try {
						MDBVal key = MDBVal.malloc(stack);
						MDBVal value = MDBVal.malloc(stack);
						int result = mdb_cursor_get(cursor, key, value, MDB_FIRST);
						while (result == MDB_SUCCESS) {
							byte[] rowKey = new byte[(int) key.mv_size()];
							byte[] rowValue = new byte[(int) value.mv_size()];
							key.mv_data().get(rowKey);
							value.mv_data().get(rowValue);
							output.writeInt(rowKey.length);
							output.write(rowKey);
							output.writeInt(rowValue.length);
							output.write(rowValue);
							result = mdb_cursor_get(cursor, key, value, MDB_NEXT);
						}
						E(result);
						output.writeInt(-1);
					} finally {
						mdb_cursor_close(cursor);
					}
				}
				byte[] catalog = LmdbBackupCatalogTestSupport.read(stack, transaction);
				assertNotNull(catalog);
				output.write(catalog);
			}
			return bytes.toByteArray();
		});
	}

	@FunctionalInterface
	private interface Mutation {
		void write(MemoryStack stack, long transaction) throws IOException;
	}

	private record Expected(Stage stage, Statement statement, byte[] bytes) {
	}

	private record Watch(long transaction, CountDownLatch reached) {
	}

	private static final class Gate {
		private final CountDownLatch selected = new CountDownLatch(1);
		private final CountDownLatch released = new CountDownLatch(1);
		private volatile boolean fail;

		private void pause() {
			selected.countDown();
			await(released, "The fixture must release publication");
			if (fail) {
				throw new SailException("Stop pending publication before native archive append for restart fixture");
			}
		}

		private void awaitSelected() {
			await(selected, "The actual publisher must select the pending suffix");
		}

		private void release() {
			released.countDown();
		}

		private static void await(CountDownLatch latch, String message) {
			try {
				assertTrue(latch.await(30, TimeUnit.SECONDS), message);
			} catch (InterruptedException interrupted) {
				Thread.currentThread().interrupt();
				throw new AssertionError(interrupted);
			}
		}
	}

